Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='migratescrub', at=datetime(2026, 10, 25, 0, 0, 0), actor='assistant', title='migrate-scrub is the standing step of every change to the redaction rules', body="Each slot records the rules it was scrubbed under (`redact::Rules`, a digest of the patterns, a `rule_version::Version` as the compactor's asking is, inside the slot's associated data): reading parses a slot under the current rules and scrubs any other as it opens, once per slot (the `Opened` cache), and `suzatary secretary migrate-scrub` (2026-10-25) is the STANDING step of every change to the rules: it appends a `Resealed` line per stale slot, its words scrubbed under the current rules under a new key, and the sweep destroys each replaced key (append and crypto-shred, nothing deleted; the old ciphertext stays in history, and a key in an earlier vault snapshot still opens it).", rationale='Decided 2026-10-25.', supersedes=()))